-- Dùng Unicode escape để migration không phụ thuộc encoding của shell Windows.
UPDATE categories c SET name = U&'T\00E0i ch\00EDnh c\00E1 nh\00E2n', name_vi = U&'T\00E0i ch\00EDnh c\00E1 nh\00E2n' FROM domains d WHERE c.domain_id=d.id AND d.code='MONEY' AND c.scope='SERIES' AND c.slug='tai-chinh-ca-nhan';
UPDATE categories c SET name = U&'K\1EF9 n\0103ng s\1ED1', name_vi = U&'K\1EF9 n\0103ng s\1ED1' FROM domains d WHERE c.domain_id=d.id AND d.code='TECH' AND c.scope='SERIES' AND c.slug='ky-nang-so';
UPDATE categories c SET name = U&'K\1EF9 n\0103ng ngh\1EC1 nghi\1EC7p', name_vi = U&'K\1EF9 n\0103ng ngh\1EC1 nghi\1EC7p' FROM domains d WHERE c.domain_id=d.id AND d.code='CAREER' AND c.scope='SERIES' AND c.slug='ky-nang-nghe-nghiep';
UPDATE categories c SET name = U&'S\1EE9c kh\1ECFe c\01A1 b\1EA3n', name_vi = U&'S\1EE9c kh\1ECFe c\01A1 b\1EA3n' FROM domains d WHERE c.domain_id=d.id AND d.code='LIFE' AND c.scope='SERIES' AND c.slug='suc-khoe-co-ban';
UPDATE categories c SET name = U&'K\1EF9 n\0103ng s\1ED1ng', name_vi = U&'K\1EF9 n\0103ng s\1ED1ng' FROM domains d WHERE c.domain_id=d.id AND d.code='LIFE' AND c.scope='SERIES' AND c.slug='ky-nang-song';
UPDATE tags SET name = CASE slug WHEN 'tai-chinh-ca-nhan' THEN U&'T\00E0i ch\00EDnh c\00E1 nh\00E2n' WHEN 'ky-nang-so' THEN U&'K\1EF9 n\0103ng s\1ED1' WHEN 'ky-nang-nghe-nghiep' THEN U&'K\1EF9 n\0103ng ngh\1EC1 nghi\1EC7p' WHEN 'suc-khoe-co-ban' THEN U&'S\1EE9c kh\1ECF\1EBB c\01A1 b\1EA3n' WHEN 'ky-nang-song' THEN U&'K\1EF9 n\0103ng s\1ED1ng' END WHERE slug IN ('tai-chinh-ca-nhan','ky-nang-so','ky-nang-nghe-nghiep','suc-khoe-co-ban','ky-nang-song');
